/// Gate 13 Redux Regression Runner
///
/// Compares benchmark results against the frozen baseline and reports pass/fail
/// for each metric using metric-specific regression thresholds.
///
/// Usage:
///   cargo bench --bench gate_13_regression_runner -- --baseline baselines/gate-13-redux.json
///
/// Output format:
///   Gate 13 Redux Regression Report
///   ───────────────────────────────
///   Metric                    Baseline    Current    Change    Threshold   Status
///   throughput_100_ops        2.134       2.128      -0.3%     ×1.10       PASS
///   throughput_1000_ops       1.583       1.590      +0.4%     ×1.15       PASS
///   ...
///   RESULT: PASS (all metrics within acceptable regression)
use serde::{Deserialize, Serialize};
use std::collections::HashMap;
use std::fs;

#[derive(Debug, Serialize, Deserialize)]
pub struct BaselineMetric {
    pub baseline: f64,
    pub variance_pct: f64,
    pub regression_threshold: f64,
    pub direction: String, // "lower_is_better" or "higher_is_better"
    pub unit: String,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct RegressionBaseline {
    pub gate: String,
    pub git_commit: String,
    pub timestamp: String,
    pub metrics: HashMap<String, BaselineMetric>,
}

#[derive(Debug)]
pub struct RegressionResult {
    pub metric_name: String,
    pub baseline: f64,
    pub current: f64,
    pub change_pct: f64,
    pub threshold: f64,
    pub status: String,
}

impl RegressionResult {
    pub fn from_measurement(
        metric_name: &str,
        baseline_metric: &BaselineMetric,
        current_value: f64,
    ) -> Self {
        let change_pct =
            ((current_value - baseline_metric.baseline) / baseline_metric.baseline) * 100.0;

        let (passes_threshold, status) = if baseline_metric.direction == "higher_is_better" {
            // For throughput/performance: lower is regression
            let threshold = baseline_metric.baseline / baseline_metric.regression_threshold;
            let passes = current_value >= threshold;
            (
                passes,
                if passes {
                    "PASS".to_string()
                } else {
                    format!("FAIL (regression: {:.1}%)", -change_pct)
                },
            )
        } else {
            // For latency/cost: higher is regression
            let threshold = baseline_metric.baseline * baseline_metric.regression_threshold;
            let passes = current_value <= threshold;
            (
                passes,
                if passes {
                    "PASS".to_string()
                } else {
                    format!("FAIL (regression: +{:.1}%)", change_pct)
                },
            )
        };

        RegressionResult {
            metric_name: metric_name.to_string(),
            baseline: baseline_metric.baseline,
            current: current_value,
            change_pct,
            threshold: baseline_metric.regression_threshold,
            status,
        }
    }

    pub fn is_pass(&self) -> bool {
        self.status.starts_with("PASS")
    }
}

/// Load baseline from JSON file
pub fn load_baseline(path: &str) -> Result<RegressionBaseline, Box<dyn std::error::Error>> {
    let content = fs::read_to_string(path)?;
    let baseline: RegressionBaseline = serde_json::from_str(&content)?;
    Ok(baseline)
}

/// Compare current measurements against baseline
pub fn check_regression(
    baseline: &RegressionBaseline,
    measurements: &HashMap<String, f64>,
) -> Vec<RegressionResult> {
    let mut results = Vec::new();

    for (metric_name, baseline_metric) in &baseline.metrics {
        if let Some(&current_value) = measurements.get(metric_name) {
            let result =
                RegressionResult::from_measurement(metric_name, baseline_metric, current_value);
            results.push(result);
        }
    }

    // Sort results: failures first, then by metric name
    results.sort_by(|a, b| {
        if a.is_pass() != b.is_pass() {
            a.is_pass().cmp(&b.is_pass())
        } else {
            a.metric_name.cmp(&b.metric_name)
        }
    });

    results
}

/// Format regression report
pub fn format_report(baseline: &RegressionBaseline, results: &[RegressionResult]) -> String {
    let mut report = format!("Gate 13 Redux Regression Report\n");
    report.push_str("───────────────────────────────\n");
    report.push_str(&format!("Baseline: {}\n", baseline.git_commit));
    report.push_str(&format!("Timestamp: {}\n\n", baseline.timestamp));

    report.push_str(&format!(
        "{:<30} {:<12} {:<12} {:<10} {:<12} {:<20}\n",
        "Metric", "Baseline", "Current", "Change", "Threshold", "Status"
    ));
    report.push_str(&"─".repeat(96));
    report.push('\n');

    for result in results {
        let baseline_metric = baseline.metrics.get(&result.metric_name).unwrap();
        report.push_str(&format!(
            "{:<30} {:<12.3} {:<12.3} {:<9.1}% {:<11.2}x {:<20}\n",
            result.metric_name,
            result.baseline,
            result.current,
            result.change_pct,
            result.threshold,
            result.status
        ));
    }

    let total = results.len();
    let passed = results.iter().filter(|r| r.is_pass()).count();
    let failed = total - passed;

    report.push('\n');
    if failed == 0 {
        report.push_str(&format!(
            "RESULT: PASS ({}/{} metrics within acceptable regression)\n",
            passed, total
        ));
    } else {
        report.push_str(&format!(
            "RESULT: FAIL ({}/{} metrics exceeded regression threshold)\n",
            failed, total
        ));
    }

    report
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_regression_detection_throughput_regression() {
        let baseline = RegressionBaseline {
            gate: "Test".to_string(),
            git_commit: "abc123".to_string(),
            timestamp: "2026-08-18T00:00:00Z".to_string(),
            metrics: {
                let mut m = HashMap::new();
                m.insert(
                    "throughput_test".to_string(),
                    BaselineMetric {
                        baseline: 1000.0,
                        variance_pct: 2.0,
                        regression_threshold: 1.10,
                        direction: "higher_is_better".to_string(),
                        unit: "Kelem/s".to_string(),
                    },
                );
                m
            },
        };

        // Current value below acceptable threshold: should FAIL
        let mut measurements = HashMap::new();
        measurements.insert("throughput_test".to_string(), 850.0); // 15% lower = fail (>10% regression)

        let results = check_regression(&baseline, &measurements);
        assert_eq!(results.len(), 1);
        assert!(!results[0].is_pass(), "Should detect regression");
    }

    #[test]
    fn test_regression_detection_latency_regression() {
        let baseline = RegressionBaseline {
            gate: "Test".to_string(),
            git_commit: "abc123".to_string(),
            timestamp: "2026-08-18T00:00:00Z".to_string(),
            metrics: {
                let mut m = HashMap::new();
                m.insert(
                    "latency_test".to_string(),
                    BaselineMetric {
                        baseline: 100.0,
                        variance_pct: 2.0,
                        regression_threshold: 1.10,
                        direction: "lower_is_better".to_string(),
                        unit: "µs".to_string(),
                    },
                );
                m
            },
        };

        // Current value above acceptable threshold: should FAIL
        let mut measurements = HashMap::new();
        measurements.insert("latency_test".to_string(), 115.0); // 15% higher = fail (>10% regression)

        let results = check_regression(&baseline, &measurements);
        assert_eq!(results.len(), 1);
        assert!(!results[0].is_pass(), "Should detect latency regression");
    }

    #[test]
    fn test_regression_passes_within_threshold() {
        let baseline = RegressionBaseline {
            gate: "Test".to_string(),
            git_commit: "abc123".to_string(),
            timestamp: "2026-08-18T00:00:00Z".to_string(),
            metrics: {
                let mut m = HashMap::new();
                m.insert(
                    "latency_test".to_string(),
                    BaselineMetric {
                        baseline: 100.0,
                        variance_pct: 2.0,
                        regression_threshold: 1.10,
                        direction: "lower_is_better".to_string(),
                        unit: "µs".to_string(),
                    },
                );
                m
            },
        };

        // Current value within threshold: should PASS
        let mut measurements = HashMap::new();
        measurements.insert("latency_test".to_string(), 108.0); // 8% higher = pass (< 10% regression)

        let results = check_regression(&baseline, &measurements);
        assert_eq!(results.len(), 1);
        assert!(results[0].is_pass(), "Should pass within threshold");
    }
}
